55	import java.io.IOException;
56	import java.io.UncheckedIOException;
57	import java.nio.charset.StandardCharsets;
58	import java.nio.file.Files;
59	import java.nio.file.Path;
60	import java.nio.file.StandardOpenOption;
61	import org.springframework.beans.factory.annotation.Value;
62	import org.springframework.stereotype.Service;
63	
64	/**
65	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
66	 * so tests can assert side-effects by reading that file — the second test-assertion channel
67	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
68	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
69	 *
70	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
71	 * SYNC) so a test reads the record immediately.
72	 */
73	@Service
74	public class Audit {
75	
76	    private final Path file;
77	
78	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
79	        this.file = Path.of(path);
80	    }
81	
82	    /** Append one audit record. Tests assert the exact line(s) in the file. */
83	    public synchronized void record(String entry) {
84	        try {
85	            Path parent = file.toAbsolutePath().getParent();
86	            if (parent != null) {
87	                Files.createDirectories(parent);
88	            }
89	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
90	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
91	        } catch (IOException e) {
92	            throw new UncheckedIOException(e);
93	        }
94	    }
95	
96	    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
97	    public synchronized void clear() {
98	        try {
99	            Files.deleteIfExists(file);
100	        } catch (IOException e) {
101	            throw new UncheckedIOException(e);
102	        }
103	    }
104	}
