124	/**
125	 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
126	 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
127	 * ARRANGE data; they ASSERT only through the UI.
128	 */
129	@Profile("e2e")
130	@RestController
131	@RequestMapping("/__test__")
132	public class TestSupportController {
133	
134	    private static final Set<String> CLIENT_FIELDS = Set.of("id", "name", "email");
135	
136	    private final Audit audit;
137	    private final JdbcTemplate jdbc;
138	
139	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
140	        this.audit = audit;
141	        this.jdbc = jdbc;
142	    }
143	
144	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
145	    @PostMapping("/reset")
146	    @Transactional
147	    public void reset() {
148	        audit.clear();
149	        jdbc.execute("DELETE FROM client");
150	        jdbc.execute("ALTER TABLE client ALTER COLUMN id RESTART WITH 1");
151	    }
152	
153	    /**
154	     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
155	     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
156	     */
157	    @PostMapping("/seed")
158	    @Transactional
159	    public void seed(@RequestBody Map<String, Object> fixture) {
160	        for (String key : fixture.keySet()) {
161	            if (!key.equals("clients")) {
162	                throw refuse("unsupported fixture key: " + key);
163	            }
164	        }
165	        for (Map<String, Object> row : rows(fixture.get("clients"), "clients")) {
166	            for (String field : row.keySet()) {
167	                if (!CLIENT_FIELDS.contains(field)) {
168	                    throw refuse("unsupported field: clients[]." + field);
169	                }
170	            }
171	            Object id = row.get("id");
172	            if (id == null) {
173	                jdbc.update("INSERT INTO client (name, email) VALUES (?, ?)",
174	                        text(row, "name"), text(row, "email"));
175	            } else {
176	                jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
177	                        ((Number) id).longValue(), text(row, "name"), text(row, "email"));
178	            }
179	        }
180	        // Keep generated ids clear of the seeded ones.
181	        Long next = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) + 1 FROM client", Long.class);
182	        jdbc.execute("ALTER TABLE client ALTER COLUMN id RESTART WITH " + next);
183	    }
184	
185	    /**
186	     * Read back what is stored, in the same shape and with the same field names the fixtures use,
187	     * so earlier checkpoints' test data can be replayed and checked (AGENTS.md §4.3, §4.4).
188	     */
189	    @GetMapping("/fixture")
190	    public Map<String, Object> fixture() {
191	        Map<String, Object> out = new LinkedHashMap<>();
192	        out.put("clients", jdbc.queryForList("SELECT id, name, email FROM client ORDER BY id").stream()
193	                .map(r -> {
194	                    Map<String, Object> row = new LinkedHashMap<>();
195	                    row.put("id", r.get("ID"));
196	                    row.put("name", r.get("NAME"));
197	                    row.put("email", r.get("EMAIL"));
198	                    return row;
199	                }).toList());
200	        return out;
201	    }
202	
203	    @SuppressWarnings("unchecked")
204	    private static List<Map<String, Object>> rows(Object value, String key) {
205	        if (value == null) {
206	            return List.of();
207	        }
208	        if (!(value instanceof List<?> list)) {
209	            throw refuse(key + " must be a list of rows");
210	        }
211	        List<Map<String, Object>> out = new ArrayList<>();
212	        for (Object o : list) {
213	            if (!(o instanceof Map<?, ?> m)) {
214	                throw refuse(key + " must be a list of rows");
215	            }
216	            out.add((Map<String, Object>) m);
217	        }
218	        return out;
219	    }
220	
221	    private static String text(Map<String, Object> row, String field) {
222	        Object v = row.get(field);
223	        return v == null ? "" : v.toString();
224	    }
225	
226	    private static ResponseStatusException refuse(String message) {
227	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, message);
228	    }
