685	# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
686	set -euo pipefail
687	cd "$(dirname "$0")/.."
688	
689	export PORT="${PORT:-3000}"
690	export BASE_URL="http://localhost:${PORT}"
691	# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
692	export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"
