699	# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
700	for i in $(seq 1 60); do
701	  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
702	  sleep 1
703	done
704	
705	# Install deps + the Chromium browser (both cached after first run), then run the specs.
706	( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
707	// Shared per-spec data setup (AGENTS.md §4). Maintained by the harness and installed into every app;
708	// do not edit the copy in the app. Each spec RESETS then SEEDS via the app's /__test__ endpoints —
709	// this is Arrange, not Assert. Specs still ASSERT only through the UI (data-testid).
710	//
711	// FAIL LOUD: reset and seed are the Arrange for EVERY spec, so they are a hard precondition — if
712	// either does not return 2xx the data is not in the state the test assumes, and a silent failure
713	// would surface later as confusing, misattributed assertion failures. We throw here so the break is
714	// attributed to the seed contract.
715	//
716	// TEST-DATA CONTRACT (AGENTS.md §4.4): before the first spec seeds anything, the fixtures of earlier
717	// checkpoints (the harness writes them to .run/fixture-contract.json — data only, never their
718	// assertions) are replayed: reset, seed, read back with GET /__test__/fixture, and every seeded
719	// field must come back with the same value. That catches a seed endpoint that stopped storing a
720	// field an earlier spec relies on — which the agent cannot otherwise see.
721	//   SEED_CONTRACT=enforce (default)  a failure fails the spec that triggered the replay
722	//   SEED_CONTRACT=report             the gate: record the result, never fail a spec
723	//   SEED_CONTRACT=off                skip
724	import { request, type APIRequestContext, type APIResponse } from '@playwright/test';
725	import { createHash } from 'node:crypto';
726	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
727	import { dirname, resolve } from 'node:path';
728	
729	const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;
730	// Playwright runs from e2e/, so the app's .run/ is one level up (as audit.ts assumes).
731	const RUN_DIR = process.env.RUN_DIR ?? resolve(process.cwd(), '..', '.run');
732	const CONTRACT_FILE = process.env.FIXTURE_CONTRACT ?? resolve(RUN_DIR, 'fixture-contract.json');
733	const RESULT_FILE = process.env.SEED_CONTRACT_RESULT ?? resolve(RUN_DIR, 'seed-contract-result.json');
734	const MODE = (process.env.SEED_CONTRACT ?? 'enforce').toLowerCase();
735	
736	async function must(res: Promise<APIResponse>, what: string): Promise<APIResponse> {
737	  const r = await res;
738	  if (!r.ok()) {
739	    const body = (await r.text().catch(() => '')).slice(0, 500);
740	    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
741	  }
742	  return r;
743	}
744	
745	export async function resetAndSeed(fixture: unknown): Promise<void> {
746	  const api = await request.newContext({ baseURL: BASE });
747	  try {
748	    await checkContractOnce(api);
749	    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
750	    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
751	  } finally {
752	    await api.dispose();
753	  }
754	}
755	
756	// ---- test-data contract replay -------------------------------------------------------------
757	
758	type DataSet = { spec: string; test: string; fixture: Record<string, unknown> };
759	type Result = { contract_sha256: string; run: number; ok: boolean; checked: number; failures: string[] };
760	
761	let checked: Promise<Result | null> | null = null;
762	
763	async function checkContractOnce(api: APIRequestContext): Promise<void> {
764	  if (MODE === 'off' || !existsSync(CONTRACT_FILE)) return;
765	  // Once per Playwright run. A worker restarts after a failed spec, so the result file is the
766	  // marker, not just this module's state — keyed by the contract AND the run (the worker's parent
767	  // is the Playwright runner). A later `bin/e2e` is a new run and replays again, so a fix to the
768	  // seed endpoint is seen at once instead of the previous run's failure being re-reported.
769	  checked ??= (async () => {
770	    const raw = readFileSync(CONTRACT_FILE, 'utf8');
771	    const sha = createHash('sha256').update(raw).digest('hex');
772	    if (existsSync(RESULT_FILE)) {
773	      const prev = JSON.parse(readFileSync(RESULT_FILE, 'utf8')) as Result;
774	      if (prev.contract_sha256 === sha && prev.run === process.ppid) return prev;
775	    }
776	    const sets = (JSON.parse(raw).data_sets ?? []) as DataSet[];
777	    const res: Result = { contract_sha256: sha, run: process.ppid, ok: true, checked: sets.length, failures: [] };
778	    if (sets.length) res.failures = await replay(api, sets);
779	    res.ok = res.failures.length === 0;
780	    mkdirSync(dirname(RESULT_FILE), { recursive: true });
781	    writeFileSync(RESULT_FILE, JSON.stringify(res, null, 2));
782	    return res;
783	  })();
784	  const res = await checked;
785	  if (res && !res.ok && MODE === 'enforce') {
786	    throw new Error(`test-data contract: ${res.failures.length} problem(s) (AGENTS.md §4.4)\n`
787	      + res.failures.slice(0, 20).join('\n'));
788	  }
789	}
790	
791	class ReadBackMissing extends Error {}
792	
793	async function readBack(api: APIRequestContext): Promise<unknown> {
794	  const r = await must(api.get('/__test__/fixture'), 'GET /__test__/fixture');
795	  // An unimplemented route typically falls through to the SPA's index.html with a 200.
796	  if (!(r.headers()['content-type'] ?? '').includes('json')) {
797	    throw new ReadBackMissing('GET /__test__/fixture does not return JSON — implement the read-back '
798	      + '(AGENTS.md §4.3) so earlier test data can be checked');
799	  }
800	  return r.json();
801	}
802	
803	async function replay(api: APIRequestContext, sets: DataSet[]): Promise<string[]> {
804	  const out: string[] = [];
805	  for (const set of sets) {
806	    const where = `  in the fixture of "${set.test}" (${set.spec.replace(/^cp\d+_/, '').replace(/\.spec\.ts$/, '')})`;
807	    try {
808	      await must(api.post('/__test__/reset'), 'POST /__test__/reset');
809	      await must(api.post('/__test__/seed', { data: set.fixture }), 'POST /__test__/seed');
810	      for (const f of compare(set.fixture, await readBack(api), '')) out.push(`the seed did not keep ${f}\n${where}`);
811	    } catch (e) {
812	      if (e instanceof ReadBackMissing) return [e.message];     // one cause, not one per fixture
813	      out.push(`${(e as Error).message}\n${where}`);
814	    }
815	    if (out.length >= 50) break;
816	  }
817	  try {
818	    // A reset must really empty the data; an endpoint that echoes its input would not.
819	    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
820	    if (!isEmpty(await readBack(api))) out.push('GET /__test__/fixture still returns rows after POST /__test__/reset');
821	  } catch (e) {
822	    out.push((e as Error).message);
823	  }
824	  return out;
825	}
826	
827	// ---- comparison (AGENTS.md §4.4: numbers by value, dates as yyyy-mm-dd, rows by id) -----------
828	
829	const DATE = /^\d{4}-\d{2}-\d{2}$/;
830	const NUMERIC = /^-?\d+(\.\d+)?$/;
831	const show = (v: unknown) => (v === undefined ? '<missing>' : JSON.stringify(v));
832	
833	function sameScalar(sent: unknown, got: unknown): boolean {
834	  if (sent === got) return true;
835	  if (got === undefined || got === null) return sent === null;
836	  if (typeof sent === 'number' || (typeof sent === 'string' && NUMERIC.test(sent))) {
837	    const a = Number(sent), b = Number(got);
838	    if (!Number.isNaN(a) && !Number.isNaN(b)) return Math.abs(a - b) < 1e-9;
839	  }
840	  if (typeof sent === 'string' && DATE.test(sent) && typeof got === 'string') return got.slice(0, 10) === sent;
841	  if (typeof sent === 'boolean') return got === sent || String(got) === String(sent);
842	  return false;
843	}
844	
845	function compare(sent: unknown, got: unknown, path: string): string[] {
846	  if (Array.isArray(sent)) {
847	    if (!Array.isArray(got)) return [`${path || 'the data'} (sent a list, read back ${show(got)})`];
848	    const out: string[] = [];
849	    for (const row of sent) {
850	      if (row && typeof row === 'object' && !Array.isArray(row) && 'id' in row) {
851	        const id = (row as { id: unknown }).id;
852	        const match = got.find((g) => g && typeof g === 'object' && sameScalar(id, (g as { id?: unknown }).id));
853	        if (!match) out.push(`${path}[id=${id}] (row missing from the read-back)`);
854	        else out.push(...compare(row, match, `${path}[id=${id}]`));
855	      } else if (!got.some((g) => compare(row, g, path).length === 0)) {
856	        out.push(`${path}[] ${show(row)} (no matching row in the read-back)`);
857	      }
858	    }
859	    return out;
860	  }
861	  if (sent && typeof sent === 'object') {
862	    if (!got || typeof got !== 'object' || Array.isArray(got)) return [`${path || 'the data'} (read back ${show(got)})`];
863	    const out: string[] = [];
864	    for (const [k, v] of Object.entries(sent)) {
865	      out.push(...compare(v, (got as Record<string, unknown>)[k], path ? `${path}.${k}` : k));
866	    }
867	    return out;
868	  }
869	  return sameScalar(sent, got) ? [] : [`${path} (sent ${show(sent)}, read back ${show(got)})`];
870	}
871	
872	function isEmpty(v: unknown): boolean {
873	  if (v === null || v === undefined) return true;
874	  if (Array.isArray(v)) return v.length === 0;
875	  if (typeof v === 'object') return Object.values(v as object).every((x) => !Array.isArray(x) || x.length === 0);
876	  return false;
877	}
